values ('ap_physics_1', 2, '2.6', array['2.6']::text[], 'convention', 'Direction and point of application of gravity', 'The gravitational force is attractive, acts along the line connecting the centers of mass of the two systems, and can be considered exerted on each system''s center of mass.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-021; ced=2.6.A.1.i, 2.6.A.1.ii, 2.6.A.1.iii')
