values ('ap_physics_1', 2, '2.6', array['2.6']::text[], 'vocabulary', 'Inertial mass vs. gravitational mass', 'Inertial mass determines how much an object''s motion resists change when interacting with another object, gravitational mass is related to the attractive force between two systems with mass, and the two have been experimentally verified to be equivalent.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-029; ced=2.6.D.1, 2.6.D.2, 2.6.D.3')
