values ('ap_physics_1', 2, '2.7', array['2.7']::text[], 'formula', 'Kinetic friction magnitude', '|\vec{F}_{f,k}|=\mu_k|\vec{F}_n|', '[]'::jsonb, NULL, 'Kinetic friction is an equality, and it does not depend on the contact surface area.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-030; ced=2.7.A.2 "product of the normal force the surface exerts on the object and the coefficient of kinetic friction"; 2.7.A.1.ii')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.7', array['2.7', '2.6', '2.9']::text[], 'vocabulary', 'Normal force', 'The normal force is the perpendicular component of the force a surface exerts on an object in contact with it, directed away from the surface.', '[]'::jsonb, NULL, 'Because it points away from the surface, the normal force need not point up: for an object on the inside of a vertical loop it points toward the center at the top. At the minimum speed there, 2.9.A.2.i has the gravitational force alone causing the centripetal acceleration, so the normal force is zero.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r3-005; ced=2.7.A.2.ii ''Normal force is the perpendicular component of the force exerted on an object by the surface with which it is in contact; it is directed away from the surface.''; po-override=product-owner ruling 2026-10-10 (David): ownership kept at the topic whose objective requires the entry, consistent with DECISION-0107 rule 2; the checkers'' earliest-mention reading is not followed; product-owner-directed correction by the Claude session (David, 2026-10-10): the escalated row was corrected against its own CED evidence and re-checked by both independent checkers and the own-family veto')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.7', array['2.7', '2.9']::text[], 'formula', 'Static friction bound and maximum', '|\vec{F}_{f,s}|\le \mu_s|\vec{F}_n|,\qquad F_{f,s,max}=\mu_s F_n', '[]'::jsonb, NULL, 'Static friction is an inequality: it adopts whatever value and direction prevents slipping, up to the maximum. Do not set it equal to \mu_s F_n unless slipping is about to begin.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-033; ced=2.7.B.2 "Static friction adopts the value and direction required to prevent an object from slipping"; 2.7.B.2.ii')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.7', array['2.7']::text[], 'convention', 'Static vs. kinetic coefficient', 'For a given pair of surfaces, the coefficient of static friction is typically greater than the coefficient of kinetic friction.', '[]'::jsonb, NULL, 'The CED says ''typically'', not always.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-034; ced=2.7.B.3 "typically greater than the coefficient of kinetic friction"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.8', array['2.8']::text[], 'convention', 'Direction of spring force', 'The force a spring exerts on an object is always directed toward the equilibrium position of the object-spring system.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-036; ced=2.8.A.3 "always directed toward the equilibrium position"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.8', array['2.8']::text[], 'formula', 'Hooke''s law', '|\vec{F}_s|=k|\Delta \vec{x}|,\qquad \vec{F}_s=-k\Delta\vec{x}', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-035; ced=2.8.A.2 "given by Hooke''s law"; 2.8.A.1 "proportional to the change in its length as measured from its relaxed length"')
