insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.8', array['2.8']::text[], 'vocabulary', 'Ideal spring', 'An ideal spring has negligible mass and exerts a force proportional to the change in its length from its relaxed length.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-037; ced=2.8.A.1 "An ideal spring has negligible mass"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.9', array['2.9']::text[], 'formula', 'Centripetal acceleration', 'a_c=\frac{v^2}{r}', '[]'::jsonb, NULL, 'Centripetal acceleration points toward the center of the circle. It is not a separate force; the net of the real forces supplies it.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-038; ced=2.9.A.1.i "ratio of the object''s tangential speed squared to the radius"; 2.9.A.1.ii')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.9', array['2.9']::text[], 'formula', 'Kepler''s third law for circular orbits', 'T^2=\frac{4\pi^2}{GM}R^3', '[]'::jsonb, NULL, 'Only circular orbits are expected; Kepler''s first and second laws are not required. M is the mass of the central body.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-044; ced=2.9.B.1 "period and radius of the circular orbit are related to the mass of the central body"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.9', array['2.9']::text[], 'formula', 'Minimum speed at top of a vertical loop', 'v=\sqrt{gr}', '[]'::jsonb, NULL, 'This holds when gravity alone supplies the centripetal acceleration at the top, so the normal force is zero.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-041; ced=2.9.A.2.i "requires a minimum speed to maintain circular motion"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
