values ('ap_physics_1', 2, '2.9', array['2.9']::text[], 'formula', 'Period and frequency', 'T=\frac{1}{f}', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-042; ced=2.9.A.5.ii "Relevant equation: T = 1/f"')
