values ('ap_physics_1', 2, '2.9', array['2.9']::text[], 'formula', 'Period of uniform circular motion', 'T=\frac{2\pi r}{v}=\frac{1}{f}', '[]'::jsonb, NULL, 'Valid only for constant speed (uniform circular motion).', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r2-012; ced=2.9.A.5.iii ''For an object traveling at a constant speed in a circular path, the period is given by the derived equation''; 2.9.A.5.ii T = 1/f')
