insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.9', array['2.9']::text[], 'convention', 'Sources of centripetal acceleration', 'Centripetal acceleration can come from a single force, several forces, or components of forces, such as normal force and static friction components on a banked surface or a tension component in a conical pendulum.', '[]'::jsonb, NULL, 'On a banked curve, quantitative analysis is expected only when no friction is required; analysis that requires friction is qualitative.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-040; ced=2.9.A.2, 2.9.A.2.ii, 2.9.A.2.iii; Boundary statement 2.9')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_physics_1', 2, '2.9', array['2.9']::text[], 'vocabulary', 'Tangential acceleration and net acceleration', 'Tangential acceleration is the rate at which an object''s speed changes, directed tangent to the circular path, and the net acceleration is the vector sum of the centripetal and tangential accelerations.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-1-reference-u1-u3-2026-10-10; candidate=ap_physics_1-u2-r1-039; ced=2.9.A.3, 2.9.A.4 "vector sum of the centripetal acceleration and tangential acceleration"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
